CARDS=[]
def add(id,module,pre,scope,method,pitfall,mastery,difficulty,variants):
 CARDS.append(dict(id=id,module=module,pre=pre,scope=scope,method=method,pitfall=pitfall,mastery=mastery,difficulty=difficulty,variants=variants))
add('CO01','系统层次与数值','程序、指令、数据的区别','存储程序、ISA、微架构、程序转换、可见寄存器和各类位宽。','先分程序员可见规范与实现细节：ISA约定指令、寄存器与寻址等，数据通路和控制实现属于微架构。编译、汇编、链接按输入输出对象辨认。','机器字长不等于指令长、地址长或浮点宽度；取指和取数依执行阶段区分；微指令不等同汇编指令。','能逐项解释何者ISA规定、何者实现选择，并由编址容量推MAR而非照抄字长。','基础到常规；混合系统层次和位宽的选项需要逐项判定。',[
('层次ISA与程序可见性','.*','PC、通用及状态等寄存器可属于ISA可见状态，IR/MAR/MDR等通常为实现内部；以题设机器为准。'),
('语言转换','编译|汇编|链接|预处理|机器语言|伪指令','预处理→编译→汇编→链接；解释逐步执行源级或中间形式，不把链接误作高级语言翻译。')])
add('CO02','系统层次与数值','单位、加权平均','CPU时间、CPI、IPC、MIPS/FLOPS及局部加速和I/O占用。','T=指令数×平均CPI/主频；平均CPI按动态指令比例加权。部分优化时拆可优化和不变时间。占用率=单位时间服务次数×每次CPU服务时间。','主频高不保证程序快；MT/s不等于MHz；等待设备时间不都占CPU；有限流水CPI不必1。','能统一秒、周期、字节和指令单位后计算；高分区分总历时与CPU忙时。','常规；条件缺失率和设备服务率串接为综合。',[
('执行时间与性能比较','CPI|MIPS|GIPS|FLOPS|主频|时钟|执行时间|加速|性能|单周期|流水|乘法','先固定同程序／同指令集等比较条件；用时间比验证加速方向。'),
('服务开销与带宽联算','中断|查询|设备|占用|每秒|带宽','按传输粒度求事件频率，再乘开销；允许响应延迟不是额外CPU服务时间。')])
add('CO03','系统层次与数值','二进制位权、模2^w','补码、符号与零扩展、类型转换、大小端、对齐及机器级截断。','先写固定位宽机器数，再做截断／扩展，最后按目标类型解释。小端低有效字节放低地址。结构体按成员对齐并将总大小补齐到所需边界。','将C语言有符号溢出一般语义说成必定回绕；本手册只按原题明确的机器截断模型计算。负数转无符号不等于改符号位。','能并列列出位模式与真值；高分追踪结构体数组步长、成员偏移和跨类型精度。','常规；连续类型转换和布局结合汇编是综合。',[
('补码及转换','补码|有符号|无符号|short|int|unsigned|signed|符号扩展|零扩展|范围|截断','w位补码范围−2^(w−1)…2^(w−1)−1；拓宽按源类型，缩窄取低位，再按目标类型解释。'),
('字节序和对齐','端|字节|对齐|结构体|成员|数组|指令','先算成员起始地址再定位某有效字节；数组步长包括结构体尾填充。'),
('整数与浮点交叉','浮点|单精度|编码','真值相同不代表机器编码相同；范围不溢出也可能丢精度，转CO05检查有效位。')])
add('CO04','系统层次与数值','补码、组合逻辑、二进制运算','整数加减、CF/OF/SF/ZF、移位、软硬件乘除与异常边界。','先按w位运算得结果；SF取最高位、ZF判全0。OF看有符号超范围，CF按题设加法进位／减法借位定义；两者独立。移位每步都按位宽截断。','把CF当有符号溢出；负数逻辑右移补符号；将浮点整体左移当乘2；先数学化简后忽略中间截断。','能算机器结果及所有要求标志；高分解释乘除硬件各寄存器职责和异常条件。','常规到较难；双字长除法和有无符号共用运算器要求多层映射。',[
('加减与条件标志','加|减|OF|CF|ZF|SF|标志|溢出|比较|补码|寄存器|下溢','同号相加得异号为加法OF；异号相减结果异于被减数为减法OF；无符号大小看借位与零。'),
('移位和截断','移位|左移|右移|shamt','算术右移补符号，逻辑右移补0，左移低位补0且高位丢弃；移位量取字段规定的有效位。'),
('乘法实现与结果宽度','乘|高半|阵列','移位加法按乘数位累加；无符号高半非0或有符号高半不是低半符号扩展时，窄结果溢出。'),
('除法与异常','除|R/Q|计数','双字长被除数由高半符号扩展和低半组成，Y存除数、计数器控迭代；除0和最小负数除−1要单独检查。')])
add('CO05','系统层次与数值','二进制小数、偏置阶码','IEEE754单精度为主的编码解码、范围、非规格化、特殊值与精度。','拆符号s、阶码E、尾数f。正规数(−1)^s(1.f)2^(E−127)，E=0非正规数(−1)^s(0.f)2^−126；E=255分无穷和NaN。','非正规数仍补隐含1；最大有限值当无穷；小数十进制有限即二进制精确；把表示范围与整数逐个精确范围混同。','能双向编码并解释特殊值；高分根据24位有效精度推相邻可表示数与舍入。','常规；非正规边界与整数转浮点失真为综合。',[
('编码解码与比较','.*','正数编码随真值单调的简化不能直接用于跨符号或NaN；比较先判符号和类型。'),
('精度与舍入','精度|精确|舍入|有效|奇整数|1.2|非精确|取偶','保留位后观察保护位、舍入位和粘滞位；恰在中点取最低保留位为偶数的结果。')])
add('CO06','系统层次与数值','浮点编码、移位','对阶、尾数运算、规格化、舍入和溢出判定。','小阶向大阶对齐且右移尾数；运算后按有效数范围左／右规格化，再舍入；舍入进位可能再次调整阶码。','只检查尾数不检查阶码；对阶丢小量导致加法不满足实数代数直觉；对IEEE整码移位。','能逐阶段写阶码和尾数并标注丢弃位；高分解释不结合及精度丢失。','综合；双符号位模型与IEEE模型不能混算。',[('运算流程与舍入','.*','原题给定阶码和尾数位宽时按该自定义格式计算；IEEE题按其规则，最终上溢判断阶码而非仅尾数临时溢出。')])
add('CO07','存储系统','地址区间、容量、位宽','芯片字位扩展、ROM/RAM分区、编址单位、寄存器宽度和对齐。','地址数=末址−首址+1；总容量=地址数×每地址单位。芯片数=(目标字数/芯片字数)×(目标位宽/芯片位宽)，按片选分组。','漏区间两端+1；按字编址仍当每址1B；MAR按已装容量而非可寻址范围；未对齐访问少算跨界。','能画字扩展片选区间并检查容量守恒；高分算跨存储字的访问次数。','常规；分区、对齐与多宽度组合为综合。',[('容量编址与扩展','.*','先统一bit/Byte/word，再分地址线和数据线；未对齐范围用首末地址覆盖的存储字计数。')])
add('CO08','存储系统','存储单元、带宽','RAM/ROM/Flash特征、DRAM行列复用刷新、SRAM与显存带宽。','按是否易失、是否刷新、可写方式及访问方式分类；DRAM地址引脚复用时由行列较大者决定，数据引脚另计。帧流量=像素数×每像素位数×帧率。','ROM不能随机读的误解；SDRAM因同步而不刷新；DDR已给有效率再乘2；显存总带宽和刷新占比未区分。','能据题中组织推行数、每行容量及引脚数；高分联合刷新开销和带宽。','基础到综合；行列组织和刷新行数优化需要约束推理。',[
('芯片性质与适用','RAM|ROM|Flash|随机|SRAM|SDRAM|TLB','SRAM常用于Cache/TLB，DRAM主存需刷新；Flash非易失，随机读取不等于可任意字节原地擦写。'),
('组织刷新与流量','行|列|引脚|刷新|显存|带宽|DDR|传输率','行列复用先分地址位，若多种最少引脚方案需再满足刷新约束；有效传输率与物理时钟分开。')])
add('CO09','存储系统','模运算、存储周期','低位交叉、同体冲突、连续存取带宽和突发时序。','按低位体号将连续字分散；某体再次启动要满足其存储周期。理想流水间隔受体数和总线传输间隔共同限制。','把字节低位直接当存储字体号而忽略编址；不支持突发仍只算一次地址阶段。','能画请求时间线并判断同体冲突；高分按首数据准备与后续间隔计算总时间。','常规到综合；交叉、对齐和总线联合时序更难。',[('交叉编址与时序','.*','体号取决于题目定义的交叉单位；8个8位芯片并成64位且按字节编址时低3位选择芯片内字节通道。')])
add('CO10','存储系统','二进制字段、数组地址','Cache直接／组相联／全相联映射、标记容量、比较器及虚实地址交叉。','块内位b=log2B，组数S=数据容量/(B×路数)，组位s=log2S，标记t=物理地址位数−s−b。总容量另加标记、有效、脏和题给替换状态。','用Cache总容量代数据容量反推；标记用虚地址高位；将路数当组数；替换状态编码不声明。','能以整除取模和位字段两种方法互检；高分说明何时组索引可由页内位直接取得。','常规到综合；TLB与Cache联合及元数据容量最易混淆。',[
('映射及地址字段','组号|字段|映射|标记|行号|块号|位数|地址|Cache行|组索引|Cache容量','块号=floor(addr/B)，组号=块号modS；有效且标记相同才命中。'),
('元数据和比较器','总容量|有效位|脏位|LRU|比较器','每组并行比较路数个标记；LRU位数按题给实现，逐行秩编码常用log2路数位，不声称这是理论最少位数。'),
('指令数据分离','分离','分离I/D Cache减少取指与数据访问的结构冲突，不消除数据相关。')])
add('CO11','存储系统','Cache映射、访问序列','命中缺失统计、LRU、数组方向和平均时间／缺失代价。','先列每次访问块号与组，组内维护LRU；首次装入和替换分开。AMAT=命中时间+缺失率×额外缺失损失，若题给的是缺失总时间则改加权平均。','非块对齐少算一块；读改写只算一次访问；按列就必然全缺失；将Cache缺失当缺页。','能由访问日志重算命中率并说明初态与写策略；高分识别容量够但组冲突的情况。','综合；跨页、非对齐与多阶段复用为较难。',[
('序列命中与置换','LRU|命中|缺失|未命中|替换|访问|块数|有效位','先查有效标记，再更新最近使用顺序；失效行先填充，满组才替换。'),
('数组与代码访问','数组|行遍历|列遍历|循环|代码|读改写|对齐|冷缺失','块数=floor(末字节/B)−floor(首字节/B)+1；能驻留且无组冲突时按列也可只发生冷缺失。'),
('时间与总线交叉','时间|CPI|代价|带宽|突发|周期','统计每指令平均缺失次数后乘额外代价；突发填块需完整总线事务时间。')])
add('CO12','存储系统','Cache与后备层','直写、回写、脏位、命中写主存以及虚存写回。','直写每次写命中也更新后备层；回写先改Cache置脏，脏块被换出才写回。写命中策略和写缺失是否分配是两个不同维度。','把直写等同不写分配；回写总是无需主存；将页回写成本与Cache回写等同。','能追踪写后哪层数据改变和脏位；高分说明未给写分配时命中率结论的假设。','常规；写策略与容量／访存次数交叉为综合。',[('写策略和状态','.*','容量题只给直写时通常无脏位；实际字数按题明确列项，不能擅加或删控制位。')])
add('CO13','存储系统','层次、局部性、虚实地址','时间空间局部性、TLB／页表／Cache关系和缺失处理。','TLB缓存地址转换，Cache缓存数据／指令；页表存在位控制是否在主存。稳定一致状态下TLB有效命中应对应驻留页。','TLB未命中一定缺页；Cache缺失一定访盘；空间局部性等同重复访问同一位置。','能画TLB→页表／异常→物理Cache的数据和控制路径；高分说明重启故障指令的位置。','基础到综合；多层命中组合需要清楚区分对象。',[('层次及局部性辨析','.*','连续地址是空间局部性，重复同地址是时间局部性；缺页由OS处理，Cache缺失通常由硬件填块。')])
add('CO14','CPU与指令','二进制编码容量','定长变长、字段宽度、扩展操作码、机器编码和后继地址。','总位宽按操作码、方式、寄存器、立即数逐项扣除；扩展操作码画前缀树，已用于短码的前缀不能再分配长码。','不同层级相同位串就一定冲突；位移有符号范围错；变长指令PC固定加字长。','能编码后再反解核对；高分计算多格式剩余编码与对齐约束。','常规到较难；扩展操作码层级和跨格式解码易误合并。',[
('字段及编码容量','字段|操作码|编码|格式|寄存器|位宽|定长|保留|指令数|指令条数|opcode','r位可编码2^r寄存器；有符号d位位移范围−2^(d−1)…2^(d−1)−1，再乘规定地址单位。'),
('指令长度及地址','PC|地址|字节|下一条|代码|隐含','下一条地址=当前地址+当前指令实际字节数；对齐可使某些地址位隐含但不缩短实际IR位宽。')])
add('CO15','CPU与指令','地址与操作数、补码','直接、间接、基址、变址、相对、带自增和复合寻址。','先写EA表达式，再决定是否访问内存取操作数。基址／变址=寄存器+位移；相对=题定PC基准+符号扩展位移×单位。','把EA当操作数；先间址再变址和先变址再间址混同；PC用当前而非已更新下一条；忽略自增时点。','能逐层写地址／内存内容；高分从机器码和指令长度恢复负分支目标。','常规到综合；变长相对转移和复合间址为较难。',[('寻址公式及执行','.*','题设寄存器编号并不决定其存的是地址还是值，寻址方式决定解释；数组比例索引必须乘元素宽度。')])
add('CO16','CPU与指令','寄存器状态、控制流','RISC/CISC、汇编与高级语言对应、循环、调用返回和指令改写。','按指令语义维护PC、寄存器、内存状态表；数组地址拆基址+行偏移+列比例；条件跳转先算标志再决定PC。','把RISC每条指令都固定单周期当绝对定义；返回可能恰好落顺序下一条；调用次数与递归深度混同。','能逐条解释并恢复表达式／循环；高分改数据类型后同时修改访存宽度与索引比例。','常规到综合；汇编、类型、寻址与异常联合属于较难。',[('风格与指令执行','.*','RISC常见Load/Store、规整格式和硬布线是组织特点；具体行为最终服从题给ISA。')])
add('CO17','CPU与指令','组合／时序逻辑、寄存器传送','数据通路连线、MUX、控制信号、单总线节拍与时钟限制。','每拍先确定源→运算→目的，再列读出使能、MUX选择和写入使能。单总线同拍只能一个源驱动，不能同时提供两独立操作数，必要时用Y/Z锁存。','数据线和控制线混画；寄存器刚写入值在同拍是否可读未按题；扩展器控制状态遗漏；无关信号写成唯一必要值。','能从微操作还原信号并反向执行检查；高分给资源约束下最少节拍及允许的无关项。','综合到较难；依原图端口与时序逐拍推理，不能用通用表替代。',[
('结构和部件','MUX|多路|三态|数据端口|连线|组合|时序|分工|控制部件|寄存器组|PC通常','MUX选择一路输入；三态门控制输出连接；寄存器存状态，ALU/MUX为组合逻辑。'),
('微操作与控制','取指|执行|节拍|单总线|ALU|移位|Load|扩展|字段|译码|控制信号','取指保留主存等待，执行信号按题的MUX编号和总线方向；不同宽度符号／零扩展需独立控制状态。'),
('时钟与周期','时钟|周期|最长路径|CPI|PC加2','单周期时钟受最长完整路径限制，多周期／流水依阶段；数据通路延迟与控制信号功能分开。')])
add('CO18','CPU与指令','编码、控制状态','硬布线与微程序、控制存储、微指令字段与控制逻辑。','互斥微操作可分组编码，每组包含无操作状态；控制地址宽度由实际微指令总数向上取log2。控制单元据操作码、状态标志和节拍产生控制。','主存与控存混同；每条指令重复统计公共取指微程序；字段编码漏无操作。','能按互斥关系分组并算位数；高分设计乘除迭代控制计数与条件分支。','常规到综合；编码约束与微程序共享段为难点。',[('控制器结构与编码','.*','硬布线通常快、修改不便；微程序灵活但有控存访问。不得把这些经验绝对化为所有实现。')])
add('CO19','CPU与指令','时钟、吞吐、延迟','流水周期、有限指令时间、吞吐率及CPI。','基本k段无阻塞流水执行n条需k+n−1周期，Tclk=max段组合延迟+题给流水寄存器延迟；吞吐=n/总时间。','用稳态吞吐替有限任务吞吐；流水CPI恒1；把每条指令延迟减为一周期。','能画装入稳态排空三部分；高分将阻塞与超标量条件分开说明。','常规；有限条与稳态混用是主要难点。',[('流水性能与适用边界','.*','仅在阶段划分、发射宽度和停顿条件满足时用基础公式；有冒险需加停顿周期。')])
add('CO20','CPU与指令','寄存器读写时点、流水阶段','结构、RAW、控制冒险与旁路、停顿、调度。','列每指令读写集合和产生／需要结果的阶段，判断值是否及时可用；旁路只改数据可达时点，不改load数据产生时点。','有旁路就无Load-use；把WAR/WAW都套到顺序五段；前段停顿未传播；漏跨循环相关。','能按题的同拍读写和分支判定阶段画时空图；高分插最少气泡并说明理由。','综合到较难；处理模型不同必须单列变式。',[
('相关与结构识别','RAW|WAW|WAR|读写|结构|分离|规整|边界','按序基本五段通常重点RAW，I/D分离解决结构冲突而非数据依赖。'),
('无旁路与同拍约束','无旁路|无转发|不可读写|跨迭代|时空图','消费者等生产者写回后才可读；同拍可否读写严格按原题，不默认半拍技巧。'),
('旁路与分支停顿','旁路|转发|Load-use|控制冒险|控制阻塞|NOP|气泡','先判断load结果何时产生；分支所需操作数及目标确定时点决定冲刷／停顿。')])
add('CO21','I/O与异常','指令执行、内核态','内异常与外中断、fault/trap/abort、返回点及算术和访存异常。','按事件来源和可恢复性分类。缺页fault处理后重做故障指令；trap通常执行后进入处理并返回后继；abort可能无法恢复。','异常发生前就必在内核态；缺页结束从下一条继续；将DMA完成当内部异常。','能给事件类别、检测时机、保存断点及返回位置；高分联动除法溢出和页面权限。','常规；细分返回点与异常触发模型为综合。',[('来源检测与返回','.*','区分发生时CPU模式、进入处理后模式及恢复位置；不能只用“中断都在指令结束”概括异常。')])
add('CO22','I/O与异常','现场、请求、服务程序','中断响应条件、屏蔽优先级、软硬件分工、嵌套和服务开销。','响应需请求、允许和未屏蔽等条件（NMI另论）；硬件保存断点／必要状态并取入口，服务软件保护通用现场、处理、恢复。屏蔽字改变可嵌套的处理次序。','响应优先级和处理优先级混同；把所有现场都交硬件；内核态不能中断；服务时间加上允许等待时间。','能编屏蔽矩阵和嵌套时间线；高分比较到达节拍与CPU服务能力。','常规到综合；屏蔽优先级与CPU占用联算为难点。',[
('响应及软硬件职责','.*','明确断点不等于全部寄存器现场；普通可屏蔽中断与NMI分开，单重和多重的开中断时点不同。'),
('频率与占用率','占用|开销|节拍|服务|到达|传输率|中断周期','每秒中断次数=字节率/每次传输字节数，乘服务时间得占用；占用超过可用CPU说明方案不可行。')])
add('CO23','I/O与异常','块传送、总线、接口','DMA初始化、总线申请、周期挪用、完成中断及占用计算。','CPU先设置地址长度方向，控制器获总线后在接口与主存间搬数据，块完通知CPU。CPU占用只计预后处理等软件工作，传输总时间另算。','DMA完全无需CPU；DMA由CPU执行逐字传送程序；总线请求次数等于块数而忽略接口宽度。','能画完整阶段并计算DMA请求次数与CPU占比；高分解释总线优先级和块间访问。','常规到综合；页大小、缺页率与传输宽度串联易错。',[('DMA过程与定量','.*','每块请求次数按每次挪用可传字节数计算；DMA优先使用总线是防设备来不及服务，不是CPU永远不能访存。')])
add('CO24','I/O与异常','设备速率、查询周期','定时查询及CPU占用和查询／中断／DMA比较。','最长查询间隔由缓冲容量/数据率决定；每秒查询次数×单次查询周期数/CPU频率给占用。','把数据等待都算查询执行；查询间隔过长导致覆盖；混淆主机与设备传输率。','能反推最低查询频率并比较服务方式的适用性。','常规；单位和缓冲粒度是关键。',[('查询周期与开销','.*','查询和中断均由CPU执行数据搬运，DMA由控制器搬运；不可仅看是否发中断来判搬运主体。')])
add('CO25','I/O与异常','bit/Byte、时钟和传输率','总线信号、标准、同步异步、突发复用、有效带宽和串行帧。','峰值=有效传输率×每次有效位宽×通道数；事务带宽=有效数据量/包含地址准备等待的总历时。异步握手以请求应答协调，不必一次只传1位。','MT/s再次乘每拍次数；地址数据复用直接增带宽；双向带宽当单向；忽略串行帧控制位。','能画一完整事务并区分峰值、有效和单向／双向；高分对非突发逐字重付准备时间。','常规到综合；多种单位和事务重叠最容易误算。',[
('带宽与事务时序','带宽|突发|传输率|周期|帧|校验|双沿|MT/s|准备','先判给的是时钟频率还是有效次数；只有前者才乘每拍次数。'),
('信号标准与组织','总线标准|USB|PCI|数据线|控制线|命令字|握手|同步|异步|串并|复用|桥接','命令字、状态字、中断类型号是数据线上的编码内容；读写、握手等控制信号走控制线。')])
add('CO26','I/O与异常','接口寄存器、地址译码','I/O端口、独立统一编址、命令状态数据与设备控制器区别。','端口是接口中的可访问寄存器；统一编址使用存储器地址体系，独立编址用专门I/O指令。命令、状态、数据的值通过数据线传输。','接口等于外设本体；I/O指令直接在外设机械部件和CPU之间传送；端口复用不分读写方向。','能指出每次读写的寄存器与信号类型，解释控制／状态端口可按方向复用。','基础到常规。',[('接口和端口辨析','.*','CPU访问的是接口端口；设备适配器／控制器连接主机与外设，数据路径依具体方式。')])
add('CO27','I/O与异常','几何编号、旋转周期、容量','磁盘容量地址、访问时间、RAID特性及SSD差异。','容量=柱面×盘面×每道扇区×扇区字节；线性块号逐级整除取模得几何地址。访问时间=寻道+旋转等待+传输+题给控制开销。','转速rpm不除60；平均旋转用整圈；RAID任何级别都冗余；SSD也按寻道模型算。','能从块／簇号换几何地址并计算时间；高分区分格式化开销、最小传输单位及文件系统块。','常规到综合；簇号跨几何层次与调度联算为难点。',[('容量地址与访问时间','容量|柱面|磁头|盘面|扇区|寻道|旋转|簇号|格式化|最小读写','平均旋转等待为半圈，仅在均匀随机相位假设下；连续传输按目标字节占整道比例。'),('RAID与SSD','RAID|SSD|磨损|条带','条带化主要提高并行性能，镜像／校验提供冗余；SSD无机械寻道但有擦写与磨损问题。')])
add('CO28','系统层次与数值','指令流、数据流、并行','超标量／超流水、SIMD/MIMD、多核多线程和SMP共享地址。','按同时处理的指令流和数据流分类；超标量提高每周期发射条数，超流水细分阶段缩短周期，二者不是同一个优化。','多核必是SIMD；单核不能硬件多线程；SMP各CPU独立地址空间；把微架构当ISA要求。','能按运行结构分类并解释CPI可能小于1的条件。','基础到常规；概念间独立维度容易混淆。',[('并行分类与性能边界','.*','向量执行常属SIMD，多核独立指令流属MIMD；共享存储和相同ISA不等于同一指令流。')])
add('CO29','系统层次与数值','二进制状态数、异或','海明码纠正一位错误所需校验位。','m位数据加r位校验，须用2^r个校验结果区分无错及m+r个单错位置，因此2^r≥m+r+1，取最小整数r。','只数数据位不数校验位也可能出错；直接套r=log2m而不向上验证。','能解释不等式来源并代入r及r−1验证最小性。','常规；低频但须保留校验位自身错误这一条件。',[('单错定位容量','.*','该不等式针对纠正单比特错误；不擅自扩张为任意多错纠正方案。')])
